class Session {
    private String state = "READY";
    boolean start() {
        if (!state.equals("READY")) {
            return false;
        }
        state = "RUNNING";
        return true;
    }
    boolean complete() {
        if (!state.equals("RUNNING")) {
            return false;
        }
        state = "DONE";
        return true;
    }
    String state() {
        return state;
    }
}

